using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private Payments.PaymentGateway _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _sut = new Payments.PaymentGateway();
    }

    // ───────────────────────────────────────────────
    //  ChargeAsync – valid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidCardTokenAndAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 49.99m;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ───────────────────────────────────────────────
    //  ChargeAsync – null / empty card token
    // ───────────────────────────────────────────────

    /// <summary>
    /// Parameterized: both null and empty-string card tokens currently
    /// throw <see cref="NotImplementedException"/> because the method
    /// body is not yet implemented.  Once implemented these should
    /// likely throw <see cref="ArgumentException"/> instead.
    /// </summary>
    [TestMethod]
    [DataRow(null, DisplayName = "Null card token")]
    [DataRow("", DisplayName = "Empty card token")]
    public async Task ChargeAsync_NullOrEmptyCardToken_ThrowsNotImplementedException(string? cardToken)
    {
        // Arrange
        var amount = 10.00m;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken!, amount));
    }

    // ───────────────────────────────────────────────
    //  ChargeAsync – boundary amounts
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 0m;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = -5.00m;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    /// <summary>
    /// Verifies the method throws for a very large charge amount.
    /// Once implemented, this may need an upper-bound validation check.
    /// </summary>
    [TestMethod]
    public async Task ChargeAsync_LargeAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 999_999.99m;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ───────────────────────────────────────────────
    //  RefundAsync – valid input
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ThrowsNotImplementedException()
    {
        // Arrange
        var chargeId = "ch_abc123";

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId));
    }

    // ───────────────────────────────────────────────
    //  RefundAsync – null / empty charge ID
    // ───────────────────────────────────────────────

    /// <summary>
    /// Parameterized: null and empty charge IDs currently throw
    /// <see cref="NotImplementedException"/>.  Once implemented these
    /// should likely throw <see cref="ArgumentException"/>.
    /// </summary>
    [TestMethod]
    [DataRow(null, DisplayName = "Null charge ID")]
    [DataRow("", DisplayName = "Empty charge ID")]
    public async Task RefundAsync_NullOrEmptyChargeId_ThrowsNotImplementedException(string? chargeId)
    {
        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId!));
    }
}

